/**
 * Returns recent historical observations for a given FRED series ID
 * @summary Get historical data for a FRED series
 */
export const getGetSeriesHistoryUrl = (
  seriesId: string,
  params?: GetSeriesHistoryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/macro/series/${seriesId}?${stringifiedParams}`
    : `/api/macro/series/${seriesId}`;
};

